 SOCKADDR_IN addr;  
 addr.sin_family=AF_INET;  
 addr.sin_addr.S_un.S_addr=htonl(INADDR_ANY);//ip地址  
 addr.sin_port=htons(6000);//绑定端口  

 bind(serSocket,(SOCKADDR*)&addr,sizeof(SOCKADDR));//绑定完成  
 listen(serSocket,5);//其中第二个参数代表能够接收的最多的连接数  

 //  
 //开始进行监听  
