  clickEvent() {
    console.log("click event")
  }

  render() {
    return (
      <div>
        <button onClick={this.clickEvent}>content 1</button>
        <button>content 2</button>
        <div className="content active">
          <h1>content 1</h1>
        </div>
        <div className="content">
          <h1>content 2</h1>
        </div>
      </div>
